  moon.position.set(-220, 340, -160);
  scene.add(moon);
  scene.add(new AmbientLight(new Color(0.3, 0.36, 0.5), 0.28));

  return {
    scene,
    camera,
    resize(w, h) {
      camera.aspect = w / Math.max(1, h);
      camera.updateProjectionMatrix();
