/**
 * Model-backed resolution: utterance -> catalogue selection.
 *
 * This is the one place in Verbo where a language model earns its keep. Everything
 * downstream is deterministic -- the brief becomes a module by template, the oracles
 * are code, the injection is code -- so a model failure degrades to a rejection rather
 * than to broken code reaching the world.
 *
 * Three things about the schema are load-bearing:
 *
 *   1. **Primitive names are an enum.** Structured outputs constrain generation at the
 *      token level, so a name outside the catalogue is not merely rejected downstream:
 *      it is unrepresentable. D-2 said the agent composes rather than invents; this is
 *      that rule expressed where it cannot be forgotten.
 *
 *   2. **`unaddressed` is required.** Constrained decoding guarantees *shape*, never
 *      *meaning* -- a schema cannot stop a model from answering a different question.
 *      Night one of the evaluation caught exactly that: "make it rain money" was
 *      accepted, because `rain` matched and `money` was silently dropped. Making the
 *      model enumerate what it could not express turns a silent omission into a field
 *      the caller has to handle.
 *
 *   3. **Parameters are not free text.** Each is clamped against the catalogue schema
 *      after parsing. A model that returns a plausible number outside a declared range
 *      would otherwise produce a candidate that fails L1 for a reason nobody can act on.
 */
import Anthropic from '@anthropic-ai/sdk';
import { z } from 'zod';
import { zodOutputFormat } from '@anthropic-ai/sdk/helpers/zod';
import type { LanguageModel } from './model.js';

/** Built from the catalogue so the enum can never drift from what exists. */
export function buildSelectionSchema(names: readonly string[]) {
  const nameEnum = z.enum(names as [string, ...string[]]);
  return z.object({
    selections: z.array(z.object({
      primitive: nameEnum,
      params: z.record(z.string(), z.union([z.number(), z.string(), z.boolean(), z.array(z.number())])),
      because: z.string(),
    })),
    /**
     * Salient parts of the request the catalogue cannot express. Required, and the
     * prompt insists on honesty here: a model that quietly returns [] while dropping
     * half the request is the failure this field exists to surface.
     */
    unaddressed: z.array(z.string()),
    confidence: z.enum(['high', 'medium', 'low']),
  });
}

export interface CatalogueEntrySummary {
  readonly name: string;
  readonly summary: string;
  readonly params: Readonly<Record<string, { type: string; min?: number; max?: number; default?: unknown }>>;
}

export interface ClaudeResolverOptions {
  readonly client?: Anthropic;
  readonly model?: string;
  /** Kept low: this is resolution, not design. Latency is a product requirement (R-8). */
  readonly effort?: 'low' | 'medium' | 'high';
}

const SYSTEM = `You resolve a request about a 3D world into primitives from a fixed catalogue.

You compose; you never invent. The catalogue is closed: if the world cannot express
something, say so in "unaddressed" rather than approximating it with whatever is
nearest.

Rules:
- Pick the fewest primitives that genuinely satisfy the request.
- Every noun or adjective in the request that the catalogue cannot express MUST appear
  in "unaddressed", verbatim. Returning an empty "unaddressed" while ignoring part of
  the request is the single worst failure available to you: the caller will report
  success for something it did not do.
- Parameters must respect the declared ranges. Prefer the default when the request
  gives no reason to move it.
- "confidence" is low when the request is ambiguous or mostly unaddressed.`;

export class ClaudeResolver implements LanguageModel {
  readonly #client: Anthropic;
  readonly #model: string;
  readonly #effort: 'low' | 'medium' | 'high';

  constructor(
    private readonly catalogue: readonly CatalogueEntrySummary[],
    options: ClaudeResolverOptions = {},
  ) {
    this.#client = options.client ?? new Anthropic();
    this.#model = options.model ?? 'claude-opus-5';
    this.#effort = options.effort ?? 'low';
  }

  async propose(utterance: string): Promise<string> {
    const schema = buildSelectionSchema(this.catalogue.map((c) => c.name));

    const response = await this.#client.messages.parse({
      model: this.#model,
      max_tokens: 4096,
      // Adaptive thinking: resolution is short but genuinely ambiguous, and the
      // interesting failure is a confident wrong pick rather than a slow right one.
      thinking: { type: 'adaptive' },
      output_config: {
        effort: this.#effort,
        format: zodOutputFormat(schema),
      },
      system: [
        {
          type: 'text',
          text: SYSTEM,
          // The system prompt and the catalogue are byte-identical on every request;
          // only the utterance varies, so the whole prefix caches.
          cache_control: { type: 'ephemeral' },
        },
        { type: 'text', text: `CATALOGUE\n${JSON.stringify(this.catalogue, null, 2)}` },
      ],
      messages: [{ role: 'user', content: utterance }],
    });

    if (!response.parsed_output) {
      throw new Error('resolver returned no parseable selection');
    }
    return JSON.stringify(response.parsed_output);
  }
}
