/**
 * WS5 · `lightning` — an occasional bright flash with a decaying afterglow.
 *
 * Catalogue slice `weather.lightning`:
 *   peak        constant  the requested peak intensity
 *   strikeRate  constant  the requested strikes per second
 *   color       vector    inside [0, 1]^3
 *   glow        animated  must move between snapshots
 *   instance    resource  present while mounted, gone after dispose()
 *
 * `glow` is the field that decides this primitive's contract, and a flash is the
 * hardest shape to publish as an honest `animated` field: the interesting part of the
 * behaviour is rare, and between two strikes a naive implementation sits at exactly
 * zero — "present but inert" (R-1) produced by a primitive that is in fact correct.
 * Three details make that impossible here:
 *
 *   1. `glow` is a *continuous exponential decay*, never a clamp to zero. Between
 *      strikes it keeps moving, so every tick changes the value the oracle reads.
 *   2. The decay can never reach zero within a strike interval. The interval drawn
 *      below is bounded above by `1.5 / frequency`, so with the schema's slowest legal
 *      rate and fastest legal decay the smallest reachable glow is `peak * e^-360` —
 *      far above where a double underflows and stops changing.
 *   3. The interval is bounded *below* by `0.5 / frequency`, which the schema keeps
 *      above `MAX_STEP_SECONDS`. Two strikes therefore cannot land on consecutive
 *      frames, so `glow` can never be reset to `peak` twice in a row and read inert
 *      while the sky is flashing as fast as it is allowed to.
 *
 * The world mounts flashing: `initial()` publishes a strike rather than darkness, so a
 * contract snapshotted before the first frame reads a live value rather than the one
 * moment this primitive legitimately looks like nothing.
 *
 * Intervals come from the seeded stream, never from `Math.random()`: an occasional
 * event is exactly the kind of thing that would make a nightly failure irreproducible.
 */
import { definePrimitive, num, vec3, type PrimitiveOptions } from './base.js';

export const LIGHTNING_STATE_PATH = 'weather.lightning';

/**
 * A strike interval, in seconds, as a fraction of the mean implied by `frequency`.
 *
 * Deliberately a bounded jitter rather than a Poisson (exponential) draw. A true
 * Poisson process admits both arbitrarily short and arbitrarily long gaps, and both
 * ends break a property above: a very short gap flashes on consecutive frames, a very
 * long one decays the afterglow past what a double can represent. Weather does not
 * care about the distinction; the oracle does.
 */
const MIN_INTERVAL_FRACTION = 0.5;
const INTERVAL_JITTER = 1;

export function createLightning(options: PrimitiveOptions = {}) {
  return definePrimitive(
    'lightning',
    {
      initial(ctx) {
        const peak = num(ctx.params, 'intensity');
        return {
          peak,
          strikeRate: num(ctx.params, 'frequency'),
          color: vec3(ctx.params, 'color'),
          // Mounted mid-strike: see the note above on why darkness is the wrong
          // initial value for a field a contract asserts over.
          glow: peak,
          flashes: 1,
          sinceFlash: 0,
          nextFlash: interval(num(ctx.params, 'frequency'), ctx.rng()),
          elapsed: 0,
          instance: ctx.id,
        };
      },
      step(state, dt, ctx) {
        const peak = num(ctx.params, 'intensity');
        const decay = num(ctx.params, 'decay');
        const frequency = num(ctx.params, 'frequency');

        state['elapsed'] = (state['elapsed'] as number) + dt;

        // The afterglow first, so a frame that also strikes ends on the strike.
        let glow = (state['glow'] as number) * Math.exp(-decay * dt);
        let since = (state['sinceFlash'] as number) + dt;
        let next = state['nextFlash'] as number;

        // `while` rather than `if` for the same reason the rain emitter recycles in a
        // loop: correct even if a host ever hands us a step longer than the clamp.
        while (since >= next) {
          since -= next;
          next = interval(frequency, ctx.rng());
          glow = peak;
          state['flashes'] = (state['flashes'] as number) + 1;
        }

        state['glow'] = glow;
        state['sinceFlash'] = since;
        state['nextFlash'] = next;
      },
    },
    options,
  );
}

/** Seconds until the next strike: the mean gap, jittered inside a bounded band. */
function interval(frequency: number, u: number): number {
  return (MIN_INTERVAL_FRACTION + INTERVAL_JITTER * u) / frequency;
}

/** The catalogue-default instance. Fresh instances come from `createLightning()`. */
export const lightning = createLightning();
