        const frequency = num(ctx.params, 'frequency');

        state['elapsed'] = (state['elapsed'] as number) + dt;

        // The afterglow first, so a frame that also strikes ends on the strike.
        let glow = (state['glow'] as number) * Math.exp(-decay * dt);
        let since = (state['sinceFlash'] as number) + dt;
        let next = state['nextFlash'] as number;

        // `while` rather than `if` for the same reason the rain emitter recycles in a
        // loop: correct even if a host ever hands us a step longer than the clamp.
        while (since >= next) {
          since -= next;
          next = interval(frequency, ctx.rng());
          glow = peak;
          state['flashes'] = (state['flashes'] as number) + 1;
        }

        state['glow'] = glow;
        state['sinceFlash'] = since;
        state['nextFlash'] = next;
      },
    },
    options,
  );
}

/** Seconds until the next strike: the mean gap, jittered inside a bounded band. */
function interval(frequency: number, u: number): number {
  return (MIN_INTERVAL_FRACTION + INTERVAL_JITTER * u) / frequency;
}

/** The catalogue-default instance. Fresh instances come from `createLightning()`. */
export const lightning = createLightning();
