        arr[i * 6 + 4] = y;
      }
      attr.needsUpdate = true;
      material.opacity = 0.2 + 0.32 * Math.min(1, count / 7000);
    },
    dispose() {
      scene.remove(rain);
      geometry.dispose();
      material.dispose();
    },
  };
};

