}

/** Deduplicated, order-preserving rotation. Empty in, empty out. */
function rotate(strategies: readonly string[], by: number): readonly string[] {
  const unique = [...new Set(strategies)];
  if (unique.length === 0) return unique;
  const at = by % unique.length;
  return [...unique.slice(at), ...unique.slice(0, at)];
}
