/**
 * The freeform surface, on screen and moving (AC-21).
 *
 * This is the one capability whose correctness cannot be established by construction.
 * Every other verb composes parameters a schema already validated, so "did it work" is
 * answerable before anything runs; a rig carries a `pose` that was *written*, and the
 * only honest answer to whether it works is a frame.
 *
 * Two things are asked, because either alone is satisfiable by a bug. That the rig is
 * *there* — a request the catalogue cannot express changed the picture — and that it is
 * *alive*: two frames a second apart differ, in a scene that is otherwise unchanged. A
 * figure standing in a T-pose passes the first and fails the second, and that figure is
 * the exact failure the freeform surface risks.
 *
 * The pixels come through the app's in-loop capture rather than a screenshot, for the
 * same reason as the rest of this directory: presentation does not survive the frame,
 * and in headless it never reaches the compositor at all (R-3).
 */
import { test, expect, type Page } from '@playwright/test';

type Api = {
  say(u: string): Promise<{ ok: boolean; reason: string | null; unaddressed?: string[] }>;
  capture(): Promise<ImageData>;
  world: { state: Record<string, unknown> };
};

async function boot(page: Page): Promise<void> {
  await page.goto('/');
  await expect(page.locator('#status')).not.toHaveText('starting', { timeout: 30_000 });
}

/**
 * Pixels that differ between two frames, ignoring the faintest.
 *
 * A threshold rather than an exact compare because the base scene is never still: the
 * moon drifts, the windows breathe, the camera orbits. What separates a moving rig from
 * that is magnitude, not presence.
 */
const DIFF = `(a, b) => {
  let n = 0;
  for (let i = 0; i < a.data.length; i += 4) {
    const d = Math.abs(a.data[i] - b.data[i])
      + Math.abs(a.data[i + 1] - b.data[i + 1])
      + Math.abs(a.data[i + 2] - b.data[i + 2]);
    if (d > 24) n++;
  }
  return n;
}`;

test.describe('a rig the catalogue cannot express (AC-21)', () => {
  test('appears on screen, and keeps moving once it is there', async ({ page }) => {
    const errors: string[] = [];
    page.on('pageerror', (e) => errors.push(e.message));
    await boot(page);

    const observed = await page.evaluate(async (diffSource) => {
      const api = (globalThis as never as Record<string, Api>)['__VERBO__']!;
      const diff = eval(diffSource) as (a: ImageData, b: ImageData) => number;
      const wait = (ms: number) => new Promise((r) => setTimeout(r, ms));

      // A control pair from the idle world, taken the same distance apart as the pair
      // after the verb. Without it this measures the orbit, not the rig: the base scene
      // moves on its own, and a threshold picked without knowing by how much would be a
      // number chosen to make the test pass.
      await wait(4_000);
      const idleA = await api.capture();
      await wait(1_000);
      const idleB = await api.capture();
      const idleMotion = diff(idleA, idleB);

      const before = await api.capture();
      const result = await api.say('un perro con una persona paseando');
      await wait(600);
      const after = await api.capture();
      await wait(1_000);
      const later = await api.capture();

      return {
        result,
        slices: Object.keys((api.world.state as Record<string, unknown>)['figures'] ?? {}),
        appeared: diff(before, after),
        motion: diff(after, later),
        idleMotion,
      };
    }, DIFF);

    expect(errors, `page errors: ${errors.join('; ')}`).toEqual([]);
    expect(observed.result.reason ?? '', 'the verb was rejected').toBe('');
    expect(observed.result.ok).toBe(true);

    // It reached the live world, under its own name, and claimed the words that
    // selected it rather than disclosing them.
    expect(observed.slices).toContain('dog-walker');
    expect(observed.result.unaddressed ?? []).toEqual([]);

    // It is on screen: the frame changed by more than the world changes on its own.
    expect(observed.appeared).toBeGreaterThan(observed.idleMotion * 1.5);

    // And it is alive. This is the assertion that a T-posed figure fails, and it is
    // compared against the idle scene rather than against zero, because zero would be
    // asking the base world to hold still and it never does.
    expect(observed.motion).toBeGreaterThan(observed.idleMotion);
  });
});
